// ─── Batch 2 | HMAC Verify + Extract ─────────────────────────────────────
// Verifies Typeform HMAC-SHA256 signature (fail-closed).
// rawBody stored in binary['data'] by Webhook rawBody:true option.
// Extracts client_slug from hidden field + candidate fields from answers.
// ─────────────────────────────────────────────────────────────────────────

const crypto = require('crypto');
const HMAC_SECRET = $env['TYPEFORM_HMAC_SECRET'];

const inputItem = $input.first();
const item      = inputItem.json;

// ── Raw body (Webhook rawBody:true stores bytes in binary['data']) ──
const b64 = inputItem.binary?.['data']?.data ?? '';
const rawBody = b64
  ? Buffer.from(b64, 'base64').toString('utf8')
  : JSON.stringify(item.body ?? {});

// ── Typeform signature header: "sha256=<hex>" ──
const sigHeader = (item.headers?.['typeform-signature'] ?? '').trim();
const signature = sigHeader.replace(/^sha256=/, '');

let valid = false;
let verifyError = null;

try {
  if (!signature) {
    verifyError = 'Missing typeform-signature header';
  } else {
    const expected = crypto
      .createHmac('sha256', HMAC_SECRET)
      .update(rawBody, 'utf8')
      .digest('hex');

    const sigBuf = Buffer.from(signature, 'utf8');
    const expBuf = Buffer.from(expected,  'utf8');

    // SHA-256 hex digests are always exactly 64 hex chars. With the 'sha256=' prefix
    // both sigBuf and expBuf are always 71 bytes for valid inputs. The explicit else
    // branch ensures fail-closed behavior survives future refactors — valid is never
    // left in its initial false state 'by accident' on a length mismatch.
    if (sigBuf.length === expBuf.length) {
      valid = crypto.timingSafeEqual(sigBuf, expBuf);
    } else {
      valid = false; // Explicit: truncated or malformed signature is always invalid
    }
  }
} catch (err) {
  verifyError = err.message;
  valid = false; // fail-closed: any crypto error = rejected
}

// ── Extract Typeform form response ──
const body         = item.body ?? {};
const formResponse = body.form_response ?? {};
const hidden       = formResponse.hidden ?? {};
const answers      = formResponse.answers ?? [];

// Build field ref → value map
const fieldMap = {};
for (const ans of answers) {
  const ref = ans.field?.ref ?? ans.field?.id ?? '';
  if (!ref) continue;
  switch (ans.type) {
    case 'text':       fieldMap[ref] = ans.text;   break;
    case 'email':      fieldMap[ref] = ans.email;  break;
    case 'number':     fieldMap[ref] = ans.number; break;
    case 'long_text':  fieldMap[ref] = ans.text;   break;
    default:           fieldMap[ref] = ans[ans.type] ?? null;
  }
}

// ── Candidate fields (field refs match Typeform form setup in SETUP.md) ──
const candidateName      = fieldMap['full_name']  ?? hidden.full_name  ?? '';
const candidateEmail     = fieldMap['email']       ?? hidden.email      ?? '';
const roleApplied        = fieldMap['role']        ?? hidden.role       ?? '';
const yearsExperience    = fieldMap['experience']  ?? '';
const coverNote          = fieldMap['cover_note']  ?? '';
const clientSlug         = hidden.client_slug      ?? 'default';
const typeformResponseId = formResponse.token      ?? body.event_id     ?? '';
const submittedAt        = formResponse.submitted_at ?? new Date().toISOString();

return [{
  json: {
    valid,
    verifyError,
    candidateName,
    candidateEmail,
    roleApplied,
    yearsExperience,
    coverNote,
    client_slug:        clientSlug,
    typeformResponseId,
    submittedAt
  }
}];

// ─── Batch 2 | Normalize Candidate ───────────────────────────────────────
// Sanitizes all candidate fields and generates idempotency key.
// Idempotency key format: idem_<base36 ts>_<random hex>_<typeform token prefix>
// Prevents duplicate processing if Typeform retries the webhook.
// ─────────────────────────────────────────────────────────────────────────

const crypto = require('crypto');
const item   = $input.first().json;

const trim      = (v) => String(v ?? '').trim();
// Strip n8n expression delimiters from free-text fields to prevent injection.
const sanitize  = (v) => trim(v).replace(/\{\{[\s\S]*?\}\}/g, '');
const titleCase = (s) =>
  s.replace(/\w\S*/g, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());

const candidateName  = titleCase(sanitize(item.candidateName));
const candidateEmail = sanitize(item.candidateEmail).toLowerCase();
const roleApplied    = sanitize(item.roleApplied);
const yearsExpRaw    = trim(String(item.yearsExperience ?? ''));
const yearsExp       = yearsExpRaw !== '' && !isNaN(Number(yearsExpRaw))
  ? Number(yearsExpRaw)
  : yearsExpRaw;
const coverNote      = sanitize(item.coverNote).substring(0, 2000);
const clientSlug     = trim(item.client_slug)
  .toLowerCase()
  .replace(/[^a-z0-9-]/g, '')
  || 'default';

// ── Email format validation ──
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(candidateEmail)) {
  throw new Error('Invalid candidate email format: ' + candidateEmail);
}

// ── Idempotency key (cryptographically secure) ──
const ts36    = Date.now().toString(36);
const rnd     = crypto.randomBytes(4).toString('hex');
const tfPfx   = (item.typeformResponseId ?? '').substring(0, 8);
const idemKey = `idem_${ts36}_${rnd}_${tfPfx}`;

return [{
  json: {
    candidateName,
    candidateEmail,
    roleApplied,
    yearsExperience:    yearsExp,
    coverNote,
    client_slug:        clientSlug,
    typeformResponseId: item.typeformResponseId ?? '',
    submittedAt:        item.submittedAt,
    idempotencyKey:     idemKey
  }
}];

// ─── Batch 2 | Check Client + Merge ──────────────────────────────────────
// UNION ALL in Postgres guarantees exactly 1 row (client_found true/false).
// Merges Postgres client config with normalized candidate data.
// Uses $() selector (n8n v1 API) to reference earlier node output.
// ─────────────────────────────────────────────────────────────────────────

const pg   = $input.first().json;
const cand = $('Normalize Candidate').first().json;

return [{
  json: {
    clientFound:        pg.client_found === true,
    // ── Candidate ──
    candidateName:      cand.candidateName,
    candidateEmail:     cand.candidateEmail,
    roleApplied:        cand.roleApplied,
    yearsExperience:    cand.yearsExperience,
    coverNote:          cand.coverNote,
    submittedAt:        cand.submittedAt,
    typeformResponseId: cand.typeformResponseId,
    idempotencyKey:     cand.idempotencyKey,
    client_slug:        cand.client_slug,
    // ── Client config (null fields when clientFound = false) ──
    clientId:       pg.id              ?? null,
    clientName:     pg.name            ?? null,
    scoreThreshold: pg.score_threshold ?? 60,
    defaultRole:    pg.default_role    ?? cand.roleApplied,
    promptTemplate: pg.prompt_template ?? '',
    successSubject: pg.success_subject ?? '',
    successBody:    pg.success_body    ?? '',
    rejectSubject:  pg.reject_subject  ?? '',
    rejectBody:     pg.reject_body     ?? ''
  }
}];

// ─── Batch 2 | Set Execution Context ─────────────────────────────────────
// Writes candidate + session metadata into $execution.customData.
// Error handler (00-error-handler) reads these fields to include
// candidate context in Slack alert cards.
// ─────────────────────────────────────────────────────────────────────────

const item = $input.first().json;

$execution.customData.set('candidate_name',  item.candidateName);
$execution.customData.set('candidate_email', item.candidateEmail);
$execution.customData.set('client_slug',     item.client_slug);
$execution.customData.set('idempotency_key', item.idempotencyKey);
$execution.customData.set('role_applied',    item.roleApplied);

return [{ json: item }]; // pass-through — full merged payload flows to Respond 200
